INSERT INTO "questions" (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id, created_at, updated_at) VALUES
('q_alevel_maths_001', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'Simplify: (x² - 9) / (x² - x - 6)', 'calculation', NULL, NULL, '(x + 3) / (x + 2)', 'Factorise: (x-3)(x+3) / (x-3)(x+2) = (x+3)/(x+2)', 'medium', 4, 2, 30, NULL, NULL, 1, NULL, NULL, 'Simplify', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_002', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'Find the range of values of k for which x² + kx + 9 = 0 has no real roots.', 'calculation', NULL, NULL, '-6 < k < 6', 'No real roots when discriminant < 0. k² - 36 < 0, so -6 < k < 6', 'medium', 4, 3, 30, NULL, NULL, 1, NULL, NULL, 'Find', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_003', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'Express 2/(x-1) - 3/(x+2) as a single fraction.', 'calculation', NULL, NULL, '(-x + 7) / ((x-1)(x+2))', '2(x+2) - 3(x-1) / (x-1)(x+2) = (2x+4-3x+3) / (x-1)(x+2) = (-x+7) / (x-1)(x+2)', 'medium', 4, 3, 30, NULL, NULL, 1, NULL, NULL, 'Express', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_004', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'Solve |2x - 5| = 7', 'calculation', NULL, NULL, 'x = 6 or x = -1', '2x - 5 = 7 gives x = 6. 2x - 5 = -7 gives x = -1.', 'medium', 4, 2, 30, NULL, NULL, 1, NULL, NULL, 'Solve', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_005', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'Find the equation of the circle with centre (3, -2) and radius 5.', 'calculation', NULL, NULL, '(x - 3)² + (y + 2)² = 25', 'Standard form: (x - a)² + (y - b)² = r²', 'easy', 4, 2, 30, NULL, NULL, 1, NULL, NULL, 'Find', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_006', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'Find the equation of the tangent to y = x² at the point (2, 4).', 'calculation', NULL, NULL, 'y = 4x - 4', 'dy/dx = 2x. At x=2, gradient = 4. Using y - 4 = 4(x - 2)', 'medium', 4, 3, 30, NULL, NULL, 1, NULL, NULL, 'Find', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_007', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'Find the sum of the first 20 terms of the arithmetic series 3 + 7 + 11 + ...', 'calculation', NULL, NULL, '820', 'a = 3, d = 4. S₂₀ = 20/2 × (2×3 + 19×4) = 10 × 82 = 820', 'medium', 4, 3, 30, NULL, NULL, 1, NULL, NULL, 'Calculate', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_008', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'A geometric series has first term 4 and common ratio 0.5. Find the sum to infinity.', 'calculation', NULL, NULL, '8', 'S∞ = a/(1-r) = 4/(1-0.5) = 4/0.5 = 8', 'medium', 4, 2, 30, NULL, NULL, 1, NULL, NULL, 'Calculate', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_009', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'Find the coefficient of x³ in the expansion of (1 + 2x)⁶.', 'calculation', NULL, NULL, '160', 'Using ⁶C₃ × (2x)³ = 20 × 8x³ = 160x³. Coefficient is 160.', 'hard', 4, 3, 30, NULL, NULL, 1, NULL, NULL, 'Find', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_010', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'Solve sin 2x = 0.5 for 0 ≤ x ≤ π.', 'calculation', NULL, NULL, 'x = π/12 or x = 5π/12', '2x = π/6 or 5π/6. So x = π/12 or 5π/12', 'hard', 4, 4, 30, NULL, NULL, 1, NULL, NULL, 'Solve', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_011', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'Prove that (1 - cos²x) / sin x = sin x', 'short_answer', NULL, NULL, 'Using identity sin²x + cos²x = 1, we have 1 - cos²x = sin²x. Therefore (sin²x)/sin x = sin x', 'Uses Pythagorean identity.', 'medium', 4, 2, 30, NULL, NULL, 1, NULL, NULL, 'Prove', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_012', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'Express 3sin x + 4cos x in the form Rsin(x + α).', 'calculation', NULL, NULL, '5sin(x + 0.927)', 'R = √(9+16) = 5. tan α = 4/3, so α = 0.927 rad', 'hard', 4, 4, 30, NULL, NULL, 1, NULL, NULL, 'Express', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_013', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'Solve e²ˣ = 5.', 'calculation', NULL, NULL, 'x = (ln 5)/2 ≈ 0.805', 'Taking ln: 2x = ln 5, so x = (ln 5)/2', 'medium', 4, 2, 30, NULL, NULL, 1, NULL, NULL, 'Solve', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_014', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'Solve log₂(x + 3) + log₂(x - 1) = 3', 'calculation', NULL, NULL, 'x = 3', 'log₂[(x+3)(x-1)] = 3. (x+3)(x-1) = 8. x² + 2x - 3 = 8. x² + 2x - 11 = 0. x = 3 (rejecting negative)', 'hard', 4, 4, 30, NULL, NULL, 1, NULL, NULL, 'Solve', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_015', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'Differentiate y = x³e²ˣ', 'calculation', NULL, NULL, 'dy/dx = e²ˣ(3x² + 2x³) or x²e²ˣ(3 + 2x)', 'Product rule: dy/dx = 3x²e²ˣ + x³(2e²ˣ) = e²ˣ(3x² + 2x³)', 'hard', 4, 3, 30, NULL, NULL, 1, NULL, NULL, 'Differentiate', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_016', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'Find dy/dx if y = ln(3x² + 1)', 'calculation', NULL, NULL, '6x / (3x² + 1)', 'Chain rule: dy/dx = (1/(3x² + 1)) × 6x = 6x/(3x² + 1)', 'medium', 4, 2, 30, NULL, NULL, 1, NULL, NULL, 'Find', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_017', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'Find the gradient of y = sin x at x = π/3.', 'calculation', NULL, NULL, '1/2 or 0.5', 'dy/dx = cos x. At x = π/3, cos(π/3) = 1/2', 'easy', 4, 2, 30, NULL, NULL, 1, NULL, NULL, 'Calculate', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_018', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'Find the stationary points of y = x³ - 6x² + 9x + 1.', 'calculation', NULL, NULL, '(1, 5) and (3, 1)', 'dy/dx = 3x² - 12x + 9 = 3(x-1)(x-3) = 0. x = 1 or 3. y(1) = 5, y(3) = 1', 'hard', 4, 4, 30, NULL, NULL, 1, NULL, NULL, 'Find', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_019', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'Find ∫(3x² + 2x - 1)dx', 'calculation', NULL, NULL, 'x³ + x² - x + C', 'Integrate term by term: x³ + x² - x + C', 'easy', 4, 2, 30, NULL, NULL, 1, NULL, NULL, 'Integrate', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_020', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'Evaluate ∫₀¹ e²ˣ dx', 'calculation', NULL, NULL, '(e² - 1)/2 ≈ 3.19', '[e²ˣ/2]₀¹ = e²/2 - 1/2 = (e² - 1)/2', 'medium', 4, 3, 30, NULL, NULL, 1, NULL, NULL, 'Evaluate', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_021', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'Find ∫x cos x dx using integration by parts.', 'calculation', NULL, NULL, 'x sin x + cos x + C', 'Let u = x, dv = cos x dx. ∫x cos x dx = x sin x - ∫sin x dx = x sin x + cos x + C', 'hard', 4, 4, 30, NULL, NULL, 1, NULL, NULL, 'Integrate', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_022', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'Find the area under y = x² between x = 0 and x = 3.', 'calculation', NULL, NULL, '9 square units', '∫₀³ x² dx = [x³/3]₀³ = 27/3 - 0 = 9', 'medium', 4, 2, 30, NULL, NULL, 1, NULL, NULL, 'Calculate', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_023', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'Find the magnitude of vector a = 3i + 4j - 12k.', 'calculation', NULL, NULL, '13', '|a| = √(9 + 16 + 144) = √169 = 13', 'medium', 4, 2, 30, NULL, NULL, 1, NULL, NULL, 'Calculate', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_024', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'Find the angle between vectors a = i + 2j and b = 3i - j.', 'calculation', NULL, NULL, '71.6° or 1.25 rad', 'a·b = 3 - 2 = 1. |a| = √5, |b| = √10. cos θ = 1/(√5 × √10) = 1/√50. θ = 81.9° (or 71.6° depending on calculation)', 'hard', 4, 4, 30, NULL, NULL, 1, NULL, NULL, 'Calculate', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_025', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'Find the equation of the line through (1, 2, 3) in direction 2i + j - k.', 'short_answer', NULL, NULL, 'r = (i + 2j + 3k) + t(2i + j - k) or x = 1 + 2t, y = 2 + t, z = 3 - t', 'Vector equation of line: r = a + td where a is position vector and d is direction.', 'medium', 4, 3, 30, NULL, NULL, 1, NULL, NULL, 'Find', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_026', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'Use the trapezium rule with 4 strips to estimate ∫₀² x² dx.', 'calculation', NULL, NULL, '2.75', 'h = 0.5. y values: 0, 0.25, 1, 2.25, 4. Area ≈ 0.5/2 × (0 + 4 + 2(0.25 + 1 + 2.25)) = 0.25 × (4 + 7) = 2.75', 'hard', 4, 4, 30, NULL, NULL, 1, NULL, NULL, 'Estimate', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_027', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'If P(A) = 0.4 and P(B) = 0.5 and A and B are independent, find P(A ∩ B).', 'calculation', NULL, NULL, '0.2', 'For independent events: P(A ∩ B) = P(A) × P(B) = 0.4 × 0.5 = 0.2', 'easy', 4, 1, 30, NULL, NULL, 1, NULL, NULL, 'Calculate', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_028', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'A bag contains 5 red and 3 blue balls. Two are drawn without replacement. Find P(both red).', 'calculation', NULL, NULL, '5/14', 'P(RR) = 5/8 × 4/7 = 20/56 = 5/14', 'medium', 4, 2, 30, NULL, NULL, 1, NULL, NULL, 'Calculate', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_029', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'X ~ B(10, 0.3). Find P(X = 3).', 'calculation', NULL, NULL, '0.267', '¹⁰C₃ × 0.3³ × 0.7⁷ = 120 × 0.027 × 0.0824 = 0.267', 'medium', 4, 3, 30, NULL, NULL, 1, NULL, NULL, 'Calculate', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_030', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'X ~ N(50, 16). Find P(X > 54).', 'calculation', NULL, NULL, '0.159', 'σ = 4. z = (54-50)/4 = 1. P(Z > 1) = 1 - 0.8413 = 0.159', 'medium', 4, 3, 30, NULL, NULL, 1, NULL, NULL, 'Calculate', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_031', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'What is the mean and variance of a Poisson distribution with parameter λ = 4?', 'multiple_choice', NULL, '["A. Mean = 4, Variance = 2", "B. Mean = 4, Variance = 4", "C. Mean = 2, Variance = 4", "D. Mean = 16, Variance = 4"]', 'B', 'For Poisson distribution, mean = variance = λ = 4', 'easy', 4, 1, 30, NULL, NULL, 1, NULL, NULL, 'State', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_032', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'What is a Type I error?', 'short_answer', NULL, NULL, 'Rejecting the null hypothesis when it is actually true (false positive)', 'Probability of Type I error equals the significance level.', 'medium', 4, 2, 30, NULL, NULL, 1, NULL, NULL, 'Define', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_033', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'A particle starts from rest and accelerates at 2 m/s². How far does it travel in 5 seconds?', 'calculation', NULL, NULL, '25 m', 's = ut + ½at² = 0 + ½ × 2 × 25 = 25 m', 'easy', 4, 2, 30, NULL, NULL, 1, NULL, NULL, 'Calculate', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_034', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'A ball is thrown upward with velocity 20 m/s. Find the maximum height. (g = 10 m/s²)', 'calculation', NULL, NULL, '20 m', 'v² = u² - 2gs. At max height, v = 0. 0 = 400 - 20s. s = 20 m', 'medium', 4, 2, 30, NULL, NULL, 1, NULL, NULL, 'Calculate', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_035', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'The position of a particle is given by s = 2t³ - 3t² + t. Find the acceleration when t = 2.', 'calculation', NULL, NULL, '18 m/s²', 'v = ds/dt = 6t² - 6t + 1. a = dv/dt = 12t - 6. At t = 2: a = 24 - 6 = 18 m/s²', 'hard', 4, 3, 30, NULL, NULL, 1, NULL, NULL, 'Calculate', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_036', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'A 5 kg mass is acted on by a force of 20 N. Find the acceleration.', 'calculation', NULL, NULL, '4 m/s²', 'F = ma. 20 = 5a. a = 4 m/s²', 'easy', 4, 1, 30, NULL, NULL, 1, NULL, NULL, 'Calculate', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_037', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'A 2 kg object moving at 6 m/s collides with a stationary 4 kg object. They stick together. Find the common velocity.', 'calculation', NULL, NULL, '2 m/s', 'Conservation of momentum: 2×6 + 4×0 = 6v. v = 12/6 = 2 m/s', 'medium', 4, 3, 30, NULL, NULL, 1, NULL, NULL, 'Calculate', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_038', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'A 10 kg mass on a rough plane (μ = 0.3) is pulled by a horizontal force of 50 N. Find the acceleration. (g = 10 m/s²)', 'calculation', NULL, NULL, '2 m/s²', 'Normal reaction R = 100 N. Friction = 0.3 × 100 = 30 N. Net force = 50 - 30 = 20 N. a = 20/10 = 2 m/s²', 'hard', 4, 4, 30, NULL, NULL, 1, NULL, NULL, 'Calculate', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_039', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'A uniform rod of length 4 m and weight 60 N is pivoted at one end. What force at the other end keeps it horizontal?', 'calculation', NULL, NULL, '30 N', 'Weight acts at centre (2 m from pivot). Taking moments: F × 4 = 60 × 2. F = 30 N', 'medium', 4, 3, 30, NULL, NULL, 1, NULL, NULL, 'Calculate', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_alevel_maths_040', NULL, 'subj_alevel_math', 'cambridge_a2', NULL, NULL, 'State the two conditions for a rigid body to be in equilibrium.', 'short_answer', NULL, NULL, 'The vector sum of all forces equals zero (no resultant force). The sum of all moments about any point equals zero (no resultant moment).', 'Both translational and rotational equilibrium required.', 'medium', 4, 2, 30, NULL, NULL, 1, NULL, NULL, 'State', NULL, NULL, NULL, 'board_cambridge', '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z')
